create table if not exists supplier_logistics_events (id bigint generated always as identity primary key,business_id uuid not null references businesses(id) on delete cascade,supplier_id uuid not null references suppliers(id) on delete restrict,purchase_order_id uuid references purchase_orders(id) on delete restrict,event_type text not null check(event_type in ('dispatch','in_transit','arrival','delay','exception','delivered')),event_reference text,quantity numeric(24,8),unit text,evidence_hash text check(evidence_hash is null or length(evidence_hash)=64),occurred_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists supplier_delivery_commitments (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,supplier_id uuid not null references suppliers(id) on delete restrict,purchase_order_id uuid not null references purchase_orders(id) on delete restrict,committed_at timestamptz not null,expected_at timestamptz not null,delivered_at timestamptz,status text not null default 'committed' check(status in ('committed','late','delivered','cancelled')),created_at timestamptz not null default now());
create index if not exists idx_v22_logistics_supplier on supplier_logistics_events(business_id,supplier_id,occurred_at desc);
create index if not exists idx_v22_commitments_due on supplier_delivery_commitments(business_id,status,expected_at);
alter table supplier_logistics_events enable row level security;
alter table supplier_delivery_commitments enable row level security;
create policy v22_logistics_select on supplier_logistics_events for select using(is_member(business_id));
create policy v22_commitments_select on supplier_delivery_commitments for select using(is_member(business_id));
create or replace function public.v22_record_supplier_logistics_event(p_business_id uuid,p_supplier_id uuid,p_purchase_order_id uuid,p_event_type text,p_event_reference text,p_evidence_hash text) returns bigint language plpgsql security definer set search_path=public as $$ declare x bigint; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if not exists(select 1 from suppliers where id=p_supplier_id and business_id=p_business_id) then raise exception 'Supplier not found for tenant'; end if; if p_purchase_order_id is not null and not exists(select 1 from purchase_orders where id=p_purchase_order_id and business_id=p_business_id) then raise exception 'Purchase order not found for tenant'; end if; if p_evidence_hash is not null and (length(p_evidence_hash)<>64 or p_evidence_hash !~ '^[0-9a-fA-F]{64}$') then raise exception 'Invalid evidence hash'; end if; insert into supplier_logistics_events(business_id,supplier_id,purchase_order_id,event_type,event_reference,evidence_hash) values(p_business_id,p_supplier_id,p_purchase_order_id,p_event_type,p_event_reference,lower(p_evidence_hash)) returning id into x; return x; end; $$;
revoke all on function public.v22_record_supplier_logistics_event(uuid,uuid,uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.v22_record_supplier_logistics_event(uuid,uuid,uuid,text,text,text) to authenticated;